import clsx from 'clsx';
import { min } from 'lodash-es';
import { useMemo, useRef } from 'react';
import { FormProvider, useForm } from 'react-hook-form';
import { 금액입력Context } from '~/widgets/exchange-convert-to-deposit-funnel/model/schemas';
import { useSetOnBack } from '~/widgets/sub-layout/use-sub-layout';
import { TransferAssetInfoFromAsset, TransferAssetInfoWrapper } from '~/entities/exchange';
import { DepositRequestDTO } from '~/entities/exchange/api/dtos/types';
import { useConvertToDepositCreateTrnscMutation } from '~/entities/exchange/api/hooks/use-switch-deposit-create-trnsc-mutation';
import {
  TransferAssetInfoArrow,
  TransferAssetInfoBank,
  TransferAssetInfoToAsset,
  TransferAssetInfoToken,
} from '~/entities/exchange/ui/transfer-asset-info';
import { AmountDisplay } from '~/entities/exchange-input-amount/ui/amount-display';
import {
  TokenInfoWrapper,
  TokenInfoAccountInfo,
  TokenInfoAvailableAmount,
  TokenInfoBankInfo,
} from '~/entities/exchange-input-amount/ui/token-info';
import { findTokenItemById, getTokenItemLabel } from '~/entities/user';
import { useGetUserInfoQuery } from '~/entities/user/api/use-get-cstmr-query';
import { getExchangeTransactionLabel } from '~/entities/wallet/lib/get-trnsc-type-label';
import { appConfig } from '~/shared/config';
import i18n from '~/shared/i18n/i18n';
import { useEffectOnceAfterPageRendered } from '~/shared/lib/hooks';

type Props = {
  context: 금액입력Context;
  onNext: ({ trnscAmt }: 금액입력Context) => void;
  onError: (error: Error) => void;
};

export const InputAmountPage = ({ onNext, onError, context }: Props) => {
  const { data: userRes } = useGetUserInfoQuery({ staleTime: 0 });
  const inputRef = useRef<HTMLInputElement | null>(null);

  const form = useForm<금액입력Context>({
    mode: 'all',
    defaultValues: { trnscAmt: context?.trnscAmt },
  });
  const {
    handleSubmit,
    register,
    formState: { errors, isValid },
    getValues,
    watch,
    setFocus,
  } = form;

  const { mutateAsync: convertToDepositCreateTrnsc } = useConvertToDepositCreateTrnscMutation();

  const watchAllFields = watch();
  const isDisabled = useMemo(() => {
    return !watchAllFields.trnscAmt || !isValid;
  }, [watchAllFields, isValid]);

  const handleClickInput = () => {
    //setFocus('trnscAmt');
    inputRef.current?.focus({ preventScroll: true });
  };

  const requestConvertToDeposit = async () => {
    const params: DepositRequestDTO = {
      tbAcnutMastr: {
        cstmrNo: userRes?.tbCstmrMastr?.cstmrNo ?? '',
        trnscAmt: getValues('trnscAmt')!.toString(),
      },
    };
    return await convertToDepositCreateTrnsc(params);
  };

  const onSubmit = async () => {
    if (isDisabled) return;

    const requestResult = await requestConvertToDeposit();

    if (requestResult.txCd) {
      onNext({
        ...context,
        trnscAmt: requestResult.amt.toString(),
        txCd: requestResult.txCd,
      });
    }
  };

  useSetOnBack(() => {
    if (window.ReactNativeWebView) {
      window.ReactNativeWebView.postMessage(JSON.stringify({ type: 'CLOSE_POPUP' }));
    } else {
      window.close(); // 브라우저 접속 시 fallback
    }
  });

  useEffectOnceAfterPageRendered(() => {
    setFocus('trnscAmt');
  });

  const tokenItem = findTokenItemById(userRes?.tbCstmrMastr?.tokenList, context.tokenId);
  const tokenLabel = getTokenItemLabel(tokenItem);

  const transactionLabel = getExchangeTransactionLabel(context.trnscTypeCd);

  const usingBankLabel = i18n.t('text:linkedAccountX', {
    x: `${userRes?.tbCstmrMastr?.bankNm} ${userRes?.tbCstmrMastr?.realAcnutNo}`,
  });

  const availableAmount = userRes?.tbCstmrMastr?.dc1CoinAmt ?? 0;
  const linkedAccountAmount = userRes?.tbCstmrMastr?.acnutnoBlce ?? 0;

  const trnscAmtRegister = register('trnscAmt', {
    required: true,
    max: {
      value: min([availableAmount, linkedAccountAmount]) ?? 0,
      message: i18n.t('insufficientBalanceConversionNotAllowed'),
    },
    min: 1,
    validate: (value) => {
      if (value && Number(value) <= 0) {
        return false;
      }
      return true;
    },
  });

  return (
    <FormProvider {...form}>
      <div className="wrap bgw">
        <div className="content sub has-btm-btn">
          <div className="sub-desc exchange">
            <p>{i18n.t('text:howMuchTo', { transactionLabel: transactionLabel })}</p>
            <TransferAssetInfoWrapper>
              <TransferAssetInfoFromAsset>
                <TransferAssetInfoToken value={tokenLabel} />
                <TransferAssetInfoBank value={appConfig.SHORT_BANK_NAME} />
              </TransferAssetInfoFromAsset>
              <TransferAssetInfoArrow />
              <TransferAssetInfoToAsset>
                <TransferAssetInfoToken value={usingBankLabel} />
              </TransferAssetInfoToAsset>
            </TransferAssetInfoWrapper>
          </div>
          <div className="ipt-form-area pay">
            <div className="ipt-form pay">
              <label className="ipt-label pay-label" htmlFor="amount">
                {i18n.t('text:enterAmount', { transactionLabel })}
              </label>
              <div className="ipt-form-box">
                <input
                  type="number"
                  className="ipt-text"
                  pattern="\d*"
                  id="amount"
                  {...trnscAmtRegister}
                  ref={(element) => {
                    trnscAmtRegister.ref(element);
                    inputRef.current = element;
                  }}
                />
                <button type="button" className="btn ipt_reset">
                  <span>{i18n.t('deleteAll')}</span>
                </button>
              </div>
            </div>
            <AmountDisplay
              trnscAmt={watchAllFields.trnscAmt ?? ''}
              error={errors.trnscAmt}
              handleClickInput={handleClickInput}
              transactionLabel={transactionLabel}
            />
            <TokenInfoWrapper>
              <TokenInfoAccountInfo label={i18n.t('walletToUse')} value={appConfig.SHORT_BANK_NAME}>
                {/* <TokenInfoBankInfo bankLabel={appConfig.SHORT_BANK_NAME} bankCode={appConfig.BANK_CODE} /> */}
                <TokenInfoBankInfo
                  bankLabel={appConfig.SHORT_BANK_NAME}
                  bankCode={appConfig.BANK_CODE}
                  dfltAliasNm={userRes.tbCstmrMastr?.dfltAliasNm}
                />
              </TokenInfoAccountInfo>
              <TokenInfoAvailableAmount amount={availableAmount} label={transactionLabel} />
            </TokenInfoWrapper>
          </div>
        </div>
        <div className="btm-btn-area">
          <button
            onClick={handleSubmit(onSubmit)}
            type="button"
            className={clsx('btm-btn app', { disabled: isDisabled })}
            id="charge"
            disabled={isDisabled}
          >
            {i18n.t('confirm')}
          </button>
        </div>
      </div>
    </FormProvider>
  );
};
