import { useMutation } from '@tanstack/react-query';
import { DepositRequestDTO, exchangeCreateTrnscResponseDTO } from '~/entities/exchange/api/dtos/types';
import { exchangeApi } from '~/entities/exchange/api/exchange-api';
import { CBDCAxiosError } from '~/shared/@types/error';
import { MutationOptions } from '~/shared/@types/query';

export const useConvertToDepositCreateTrnscMutation = (
  options?: MutationOptions<DepositRequestDTO, CBDCAxiosError, exchangeCreateTrnscResponseDTO>,
) => {
  const mutation = useMutation<exchangeCreateTrnscResponseDTO, CBDCAxiosError, DepositRequestDTO>({
    ...options,
    mutationFn: exchangeApi.convertToDepositCreateTrnsc,
  });

  return {
    ...mutation,
  };
};
